    case 177: return termSempred(antlrcpp::downCast<TermContext *>(context), predicateIndex);
    case 181: return primarySempred(antlrcpp::downCast<PrimaryContext *>(context), predicateIndex);
    case 242: return t_primarySempred(antlrcpp::downCast<T_primaryContext *>(context), predicateIndex);

